    "tool tips": {
        "Sentinel variant rsID": "rsID of the sentinel variant at the GWAS significant locus",
        "Sentinel variant chromosome:position": "Chromosome:position of the sentinel variant at the GWAS significant locus",
 "Gene": "Gene at the GWAS significant locus to which the evidence row pertains",
        "Nearest gene": "Whether the gene is the closest gene to the sentinel variant",
        "MAGMA evidence": "Whether the gene has a MAGMA significant association with heart failure, is within a 2MB window around the sentinel variant, and has median (transcripts per kilobase million) >1 in at least one GTEx heart tissue",
        "LD with missense SNP": "Whether a missense SNP in the gene is in linkage disequilibrium (r2 > 0.8) with the sentinel variant",
        "Heart cis-eQTL": "Whether expression levels of the gene are associated with the sentinel variant in heart tissues (left atrium and right atrium auricular region; data from the MAGNet and GTEx projects)",
        "Heart colocalization": "Whether a heart failure-associated variant within a 200kb window around the gene colocalizes with a heart tissue eQTL for the gene with posterior probability of ≥0.7, as determined by the coloc method",
        "Heart MetaXcan": "Whether expression levels of the gene in heart tissue, predicted by the S-PrediXcan method, are significantly associated with heart failure risk",
        "Blood cis-eQTL": "Whether expression levels of the gene are associated with the sentinel variant in whole blood (data from the eQTLGen consortium)",
        "Blood colocalization": "Whether a heart failure-associated variant within a 200kb window around the gene colocalizes with a whole blood eQTL for the gene with posterior probability of ≥0.7, as determined by the coloc method",
        "Blood cis-pQTL": "Whether protein levels of the gene product, based on measures for serum proteins mapping to 3000 genes in 3301 healthy individuals from the INTERVAL study, are associated with the sentinel variant",
        "Number of lines of evidence": "The number of positive lines of evidence in a row."
  }
}

